function title(f){return names[f.id]||videoInfo[f.id]?.title||f.label||f.name.replace(/\.docx$|\.pdf$/gi,'').replace(/^\d+\s*\|\s*/,'');}
function size(n){return n>=1e9?(n/1e9).toFixed(2).replace('.',',')+' GB':n>=1e6?(n/1e6).toFixed(1).replace('.',',')+' MB':Math.max(1,Math.round(n/1000))+' KB';}
function fmt(f){return f.mime==='application/vnd.google-apps.document'?'LINK CANVA':f.mime.split('/')[1].includes('wordprocessing')?'DOCX':f.mime==='image/svg+xml'?'SVG':f.mime.split('/')[1].toUpperCase();}
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
