function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Texto copiado. Pronto para adaptar à sua conversa.')}catch{const ta=document.createElement('textarea');ta.value=t;$('#viewer').open?$('#viewer-content').append(ta):document.body.append(ta);ta.select();const ok=document.execCommand('copy');ta.remove();toast(ok?'Texto copiado.':'Não foi possível copiar. Selecione o texto e copie manualmente.')}}
const external=(url,label,cls='text-link')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} <span aria-hidden="true">↗</span></a>`;
