function copyBlock(key,label,text){copyTexts[key]=text;return `<div class="copy-block"><span class="tag">${label}</span><blockquote>${esc(text)}</blockquote><button class="button outline small" data-copy="${key}">Copiar texto <span aria-hidden="true">⧉</span></button></div>`}
function materialCard(f){
 const isVideo=f.category==='videos';const isImage=!!f.preview;
 const preview=brandPreviewFiles[f.id]||f.preview||documentPreviews[f.id]||cardPreviews[f.id]||videoInfo[f.id]?.image||(f.id===guideId?'assets/guia-capa.webp':null);
 const mediaClass=f.category==='marca'?(lightBrandBackgrounds.has(f.id)?' logo logo-on-light':' logo'):fullPhotoPreviews.has(f.id)?' full-photo-preview':f.id===checklistId?' checklist-cover':documentPreviews[f.id]||cardPreviews[f.id]?' promo document-preview':f.category==='redes'?' promo':'';
 const previewAlt=documentPreviews[f.id]?'Primeira página de '+title(f):isImage?title(f):'Prévia ilustrativa de '+title(f);
 const label=f.id===canvaId||f.name.includes('EDITÁVEL')?'Para personalizar':cats[f.category];
 return `<article class="material"><button class="material-media${mediaClass}" data-view="${f.id}" aria-label="${isVideo?'Assistir':'Visualizar'}: ${esc(title(f))}">${f.id===checklistId?checklistPreview(true):preview?`<img src="${preview}" alt="${esc(previewAlt)}" loading="lazy">`:`<span class="file-symbol" aria-hidden="true">${f.id===canvaId?'Aa':fmt(f)}</span>`}${isVideo?'<span class="play" aria-hidden="true">▶</span>':''}</button><div class="material-body"><span class="tag">${label}</span><h3>${esc(title(f))}</h3><p class="meta">${fmt(f)}${f.bytes?' · '+size(f.bytes):''}${f.id===guideId?' · 28 páginas':''}</p><div class="card-actions"><button class="button outline small" data-view="${f.id}">${isVideo?'Assistir':isImage?'Ampliar':f.id===canvaId?'Personalizar':'Visualizar'}</button>${external(f.url,'Drive')}<button class="save" data-save="${f.id}" aria-label="${favorites.has(f.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(title(f))}" aria-pressed="${favorites.has(f.id)}">${favorites.has(f.id)?'★':'☆'}</button></div></div></article>`;
}
function guideBanner(){return `<div class="guide-banner"><img src="assets/guia-capa.webp" alt="Capa do Guia Comercial do Parceiro"><div><span class="eyebrow">SEU MATERIAL DE CONSULTA</span><h3>Conhecer bem a experiência é o primeiro passo para vender melhor.</h3><p>Use o guia como apoio nas conversas com escolas, adapte sua abordagem ao perfil de cada instituição e utilize os materiais oficiais para construir sua comunicação.</p><button class="button" data-view="${guideId}">Consultar guia completo ↗</button><p class="source">PDF original · 28 páginas · 159,3 MB</p></div></div>`}
