function know(){return pageHead('A EXPERIÊNCIA','Conteúdo que ganha vida.<br>Aprendizagem que deixa referências.','Um espaço com ambientação medieval, atividades pedagógicas e momentos lúdicos para aproximar os estudantes dos conteúdos trabalhados na escola.')+`<div class="wrap"><div class="intro-facts"><div><strong>6º e 7º anos</strong><span>Indicação principal</span></div><div><strong>4 estações</strong><span>Temas históricos e participação</span></div><div><strong>Dia inteiro</strong><span>Com almoço na programação</span></div><div><strong>São Roque</strong><span>Interior de São Paulo</span></div></div>
<section class="section"><div class="split"><div><span class="eyebrow">MUITO ALÉM DO CENÁRIO</span><h2>O aluno observa, participa e constrói relações.</h2><p>A ambientação ajuda a transformar conteúdos que poderiam parecer distantes em algo mais próximo, visual e concreto. Os educadores conduzem a experiência com mediação pedagógica e atuação teatral.</p><p>O Castelo é uma representação didática e imersiva inspirada no universo medieval. Os espaços foram adaptados para a visitação escolar e não se apresentam como uma reconstrução histórica exata.</p><button class="button" data-view="${commercialId}">Assistir à apresentação ▷</button></div><img class="split-image" src="${photo(3)}" alt="Equipe caracterizada diante da fachada de O Castelo"></div></section>
<section class="section compact"><div class="section-head"><div><span class="eyebrow">QUATRO ESTAÇÕES, DIFERENTES OLHARES</span><h2>Entre na experiência.</h2></div><p>Defesa, poder, religiosidade, trabalho e cotidiano: cada ambiente abre uma conversa sobre a sociedade medieval.</p></div><div class="station-grid">${[
['Muralha','Defesa, território e organização dos espaços. Uma oportunidade para observar como a construção se relaciona com a proteção e o poder.','1Dd9MCUIvjWQCP1XnIU6affUQFk4FpGaG',2],
['Salão dos Nobres','Hierarquia social, autoridade e relações de poder. O cenário contribui para contextualizar o papel da nobreza.','1Ge6EPG88uKSBMe4Fu1GF28fA6Zv2d4Wr',14],
['Capela','Religiosidade e influência da Igreja na vida medieval, em uma abordagem histórica e orientada.','1qzbJJ7Fe5pY77Q1ohDnJAEK0vikf3B8X',15],
['Vila Camponesa','Trabalho, produção e vida cotidiana. Os estudantes entram em contato com temas ligados às relações sociais do mundo medieval.','1PiIaln0Gbmgw8Zj6_pVLEocF15NoPj08',25]
].map(([t,d,id,i],n)=>`<article class="station"><img src="${photo(i)}" alt="${t} — imagem do acervo oficial" loading="lazy"><div class="station-content"><span class="tag">AMBIENTE ${String(n+1).padStart(2,'0')}</span><h3>${t}</h3><p>${d}</p><button class="button outline small" data-view="${id}">Assistir ao vídeo ▷</button></div></article>`).join('')}</div><p class="source">Síntese editorial dos FAQs pedagógico e de experiência. Imagens do banco oficial. A ordem das estações depende da organização da visita.</p></section>
<section class="section"><span class="eyebrow">UM DIA DE VIVÊNCIAS</span><h2>Como a visita acontece.</h2><div class="timeline"><div><strong>09H / 09H30</strong><h3>Chegada</h3><p>Recepção e organização dos estudantes em grupos menores.</p></div><div><strong>MANHÃ</strong><h3>Observar e participar</h3><p>Duas estações com mediação pedagógica e vivências lúdicas.</p></div><div><strong>PAUSA PARA ALMOÇO</strong><h3>Compartilhar</h3><p>Almoço do grupo escolar no local, incluído na experiência.</p></div><div><strong>TARDE · ATÉ 16H / 16H30</strong><h3>Ampliar descobertas</h3><p>Mais duas estações e encerramento da programação.</p></div></div><div class="callout">Os horários são referências e devem ser alinhados com a equipe do Castelo. Transporte, acompanhamento no trajeto e outros serviços fazem parte da organização combinada entre a agência e a escola.</div>${source('FAQ — Experiência e dinâmica',find('11kpeYF-AUDemiw7qiW3zOwheE3KAU5mp').url)}</section>
<section class="section compact"><div class="split"><div><span class="eyebrow">CONEXÃO COM A ESCOLA</span><h2>O pedagógico e o lúdico caminham juntos.</h2><p>As atividades podem complementar conteúdos escolares e criar oportunidades para trabalhar competências e habilidades previstas na BNCC. O roteiro amplia possibilidades de abordagem por meio da experiência.</p><a class="button" href="#vendas">Como apresentar à escola ↗</a></div><div><blockquote class="quote">“Quais conteúdos vocês estão trabalhando com essa turma?”</blockquote><p>A resposta ajuda a conectar a experiência ao planejamento do professor.</p><a class="text-link" href="#duvidas?tema=01">Consultar dúvidas pedagógicas ↗</a></div></div></section></div>`}
function sales(){return pageHead('GUIA COMERCIAL DO PARCEIRO','Tudo o que sua equipe precisa<br>para apresentar, argumentar e vender.','Use estas orientações nas conversas com escolas. Adapte a abordagem ao perfil de cada instituição e construa sua comunicação com os materiais oficiais.')+`<section class="section"><div class="wrap content-layout"><aside class="side-nav" aria-label="Neste guia">${[['comecar','Comece pela experiência'],['interlocutores','Com quem conversar'],['beneficios','Características e benefícios'],['bncc','Como falar sobre BNCC'],['apresentacoes','Apresentações rápidas'],['objecoes','Respostas a objeções'],['valor','Como apresentar valor']].map(([id,t])=>`<a href="#vendas/${id}">${t}</a>`).join('')}<button class="button outline small" style="margin-top:20px" data-view="${guideId}">Abrir guia original ↗</button></aside><div class="editorial">
<section id="comecar"><span class="eyebrow">01 · COMO VENDER O CASTELO</span><h2>Não comece vendendo o lugar.<br>Venda a experiência.</h2><p>O primeiro passo para vender melhor é saber identificar para quem apresentar a experiência. O cenário contribui para a proposta: os alunos têm contato com atividades pedagógicas e lúdicas que estimulam curiosidade, participação, interação e aprendizagem.</p>${copyBlock('abertura','UMA FORMA SIMPLES DE INICIAR A CONVERSA','Estamos incluindo em nosso portfólio uma nova experiência pedagógica em São Roque. O roteiro acontece em um espaço com ambientação medieval e reúne atividades pedagógicas e lúdicas pensadas para aproximar os estudantes de conteúdos trabalhados em sala. Gostaria de apresentar a proposta para vocês.')}</section>
<section id="interlocutores"><h2>Para quem apresentar?</h2><p>Priorize o contato com coordenação pedagógica, direção, professores, responsáveis por projetos interdisciplinares e por saídas e viagens pedagógicas.</p><div class="benefits"><div class="benefit"><h3>Coordenação pedagógica</h3><p>Apresente a proposta, a participação dos estudantes, as possibilidades de conexão curricular, as atividades, a faixa etária, a estrutura e a organização da visita.</p></div><div class="benefit"><h3>Professor</h3><p>Mostre como a visita pode ampliar aquilo que já está sendo desenvolvido em sala. Pergunte quais conteúdos estão sendo trabalhados com a turma.</p></div><div class="benefit"><h3>Direção</h3><p>Destaque qualidade da experiência, organização, proposta pedagógica, segurança, relacionamento com as famílias e valor percebido.</p></div><div class="benefit"><h3>Escolas com maior potencial</h3><p>Instituições que valorizam aprendizagem fora da sala, estudos do meio, propostas interdisciplinares e novos destinos para seus alunos.</p></div></div>${copyBlock('novidades','PARA ESCOLAS QUE BUSCAM UM NOVO ROTEIRO','Se vocês estão buscando um destino diferente para o calendário de saídas pedagógicas, temos uma experiência nova que vale conhecer. O Castelo une ambientação medieval, atividades e conteúdo pedagógico em uma proposta criada especialmente para estudantes.')}${copyBlock('conteudo','PARA ESCOLAS QUE JÁ TRABALHAM O CONTEÚDO','Esse roteiro pode ser uma oportunidade interessante para ampliar, por meio da vivência, conteúdos que os alunos já estão trabalhando em sala. A experiência utiliza o universo medieval como contexto para atividades pedagógicas e lúdicas.')}</section>
<section id="beneficios"><h2>Transforme características<br>em benefícios.</h2><div class="benefits"><div class="benefit"><h3>Ambientação medieval</h3><p>A ambientação ajuda o aluno a visualizar e contextualizar um universo histórico que normalmente conhece apenas por livros, imagens e conteúdos apresentados em sala.</p></div><div class="benefit"><h3>Atividades lúdicas</h3><p>As atividades lúdicas criam momentos de participação que ajudam a manter os estudantes envolvidos durante a experiência.</p></div><div class="benefit"><h3>Proposta pedagógica</h3><p>A proposta permite que conteúdos trabalhados pela escola sejam retomados de outra forma, por meio da experiência.</p></div><div class="benefit"><h3>Participação e memória</h3><p>O aluno é convidado a observar, participar, interpretar e construir relações. Quando um conteúdo é associado a uma atividade ou descoberta, ele pode ganhar novos significados.</p></div></div></section>
<section id="bncc"><span class="eyebrow">02 · COMO ARGUMENTAR COM A ESCOLA</span><h2>Como falar sobre BNCC.</h2><p>Evite promessas genéricas. A BNCC faz parte do embasamento pedagógico, e a conversa deve se conectar ao planejamento da escola.</p>${copyBlock('bncc','UMA FORMULAÇÃO DO SCRIPT COMERCIAL','A experiência cria possibilidades de conexão com competências, habilidades e conteúdos trabalhados pela escola e previstos na BNCC.')}<p>As atividades ampliam conteúdos desenvolvidos em sala de aula por meio da vivência e da participação dos estudantes. A relação com o currículo pode ser aprofundada conforme o ano escolar e os objetivos dos professores.</p><a class="text-link" href="#duvidas?tema=01">Aprofundar as questões pedagógicas ↗</a></section>
<section id="apresentacoes"><h2>Uma apresentação para<br>cada conversa.</h2>${copyBlock('30seg','O CASTELO EM 30 SEGUNDOS · GUIA ORIGINAL','O Castelo é uma experiência pedagógica realizada em São Roque, em um espaço com ambientação medieval. O roteiro combina atividades pedagógicas e lúdicas para que os estudantes não apenas conheçam o tema, mas participem da experiência. É uma alternativa interessante para escolas que buscam novos estudos do meio, com possibilidades de conexão com conteúdos e habilidades trabalhados no currículo.')}${copyBlock('ampliada','APRESENTAÇÃO DA EXPERIÊNCIA · GUIA ORIGINAL','O Castelo é uma experiência pedagógica em São Roque criada para aproximar os estudantes do universo medieval por meio de uma proposta que combina ambientação, atividades pedagógicas e momentos lúdicos. O grande diferencial é que o cenário não funciona apenas como decoração: ele contribui para contextualizar aquilo que está sendo trabalhado.')}</section>
<section id="objecoes"><h2>Quando a escola perguntar…</h2>${copyBlock('passeio','“MAS É UM PASSEIO OU É PEDAGÓGICO?”','É uma experiência pedagógica que utiliza elementos lúdicos como recurso de participação. A proposta não é transformar o aprendizado em uma aula tradicional fora da escola, mas criar situações em que conteúdo, cenário e experiência possam se complementar.')}${copyBlock('ludico','COMO FALAR SOBRE O LÚDICO','O pedagógico e o lúdico aparecem de forma integrada ao longo da experiência. O lúdico pode ser justamente o recurso utilizado para aumentar o envolvimento do estudante com determinada proposta.')}${copyBlock('preco','QUANDO O PREÇO VIRAR UMA OBJEÇÃO','Entendo. Quando analisamos o investimento, acho importante considerar não apenas o acesso ao espaço, mas toda a experiência proposta aos estudantes, as atividades, a estrutura e também tudo o que está incluído na operação organizada pela agência.')}<p>Retome o valor da experiência antes de avaliar as possibilidades comerciais.</p></section>
<section id="valor"><span class="eyebrow">03 · COMO APRESENTAR VALOR</span><h2>Antes de apresentar o investimento, construa valor.</h2><ol><li>Apresente o conceito da experiência.</li><li>Mostre o que o aluno vivencia.</li><li>Explique os diferenciais.</li><li>Conecte a proposta pedagógica ao planejamento da escola.</li><li>Deixe claro o que está incluído no pacote da agência.</li></ol>${copyBlock('pacote','EXEMPLO DE APRESENTAÇÃO COMERCIAL','Além da experiência de O Castelo, nossa proposta contempla toda a operação organizada pela agência, incluindo os serviços combinados para esta saída pedagógica. O investimento por aluno será apresentado conforme a data, o número de participantes e os itens incluídos no pacote.')}<div class="callout"><strong>Não prometa o que não está confirmado.</strong><p>Antes de fechar uma proposta, consulte os dados atualizados disponibilizados oficialmente por O Castelo. Diferencie a experiência no local dos serviços organizados pela agência.</p></div><a class="button" href="#proposta">Preparar a proposta ↗</a>${source()}${source('Script — Argumentos de venda',find(scriptId).url)}</section></div></div></section>`}
function campaigns(){return pageHead('MATERIAIS PARA CAMPANHAS','Sua escola. Sua comunicação.<br>Os materiais oficiais de O Castelo.','Encontre peças para divulgação, personalize sua condição comercial e escolha fotos, vídeos e logos para construir sua campanha.')+`<section class="section"><div class="wrap"><div class="campaign-banner"><img src="assets/1Skjamrx2OIkW-B4B6eT9nEIO608_afkL.webp" alt="Peça oficial da agenda 2027 para feed"><div><span class="eyebrow">CAMPANHA · AGENDA 2027</span><h2>Uma viagem ao tempo<br>na Idade Média.</h2><p>Peças oficiais para apresentar a experiência às suas escolas e divulgar a agenda nas redes sociais.</p><div class="hero-actions"><button class="button" data-view="1Skjamrx2OIkW-B4B6eT9nEIO608_afkL">Ver peça para feed ↗</button><button class="button outline" data-view="1c_BA40CDc8QkOULV1dr4XwfSc3a2S5J0">Ver stories e status ↗</button></div><p class="source">Feed: 1080 × 1350 px · Stories/status: 1080 × 1920 px</p></div></div></div></section>
<section class="section white"><div class="wrap"><div class="section-head"><div><span class="eyebrow">PERSONALIZE SUA OFERTA</span><h2>A identidade de O Castelo.<br>A proposta da sua agência.</h2></div><p>O modelo de condição especial tem espaço para preço, validade, logo e contato. Preencha e confira esses campos antes de divulgar.</p></div><div class="grid">${[canvaId,'1xjULSWnp9cWQ9SMpxfHMHovKpFd2tgUj','1zPykHdQ469_8IsKOGwEJ1i8dYMx6coBU'].map(id=>materialCard(find(id))).join('')}</div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">COMPONHA SUA COMUNICAÇÃO</span><h2>Um acervo à sua disposição.</h2></div></div><div class="journeys">${[['fotos','Fotografias',libraryFiles.filter(f=>f.category==='fotos').length+' imagens da ambientação, dos personagens e da experiência.'],['videos','Vídeos','Apresentação comercial e quatro estações para assistir e baixar.'],['marca','Identidade visual','Logos e avatar em diferentes versões e formatos.'],['comercial','Apoio comercial','Guia, argumentos de venda e checklist para sua equipe.'],['todos','Biblioteca completa','Encontre todos os materiais em um só lugar.']].map(([c,t,d],i)=>`<a class="journey" href="#biblioteca?categoria=${c}"><span class="number">0${i+1}</span><h3>${t}</h3><p>${d}</p><span class="arrow">↗</span></a>`).join('')}</div><div class="callout"><strong>Para preparar folhetos e apresentações:</strong> combine fotos e logos oficiais com a linguagem do guia. O arquivo de impressos disponível é o incentivo ao check-in digital; um folheto comercial completo ainda não faz parte deste acervo.</div></div></section>`}
function videosPage(){return pageHead('BANCO DE VÍDEOS','Assista. Conheça.<br>Apresente à sua escola.','Explore o vídeo comercial e os quatro vídeos das estações. Assista aqui no portal ou abra o original no Drive para baixar e usar na sua comunicação.')+`<section class="section"><div class="wrap"><button class="video-feature" data-view="${commercialId}"><img src="${photo(41)}" alt="Fachada de O Castelo"><div><span class="eyebrow" style="color:#e2c78f">APRESENTAÇÃO COMERCIAL</span><span class="big-play" aria-hidden="true">▶</span><h3>O Castelo em vídeo.</h3><span>Assistir à apresentação completa ↗</span></div></button><p class="source">Reprodução pelo Google Drive, com internet. Arquivo original: ${size(find(commercialId).bytes)}. O download é opcional.</p><div class="section-head" style="margin-top:60px"><div><span class="eyebrow">CONHEÇA OS AMBIENTES</span><h2>Quatro estações.<br>Quatro formas de explorar.</h2></div></div><div class="grid four">${files.filter(f=>f.category==='videos'&&f.id!==commercialId).map(materialCard).join('')}</div></div></section>`}
function library(){return pageHead('BIBLIOTECA DO PARCEIRO','Tudo para apoiar<br>a sua próxima campanha.','Fotos, vídeos, peças e documentos oficiais. Encontre o que precisa, visualize e acesse o arquivo original no Drive.')+`<section class="section"><div class="wrap"><div class="toolbar"><label class="search"><span class="visually-hidden">Buscar materiais</span><input type="search" id="material-search" placeholder="Busque por nome, formato ou assunto…" value="${esc(filters.query)}"></label><label><span class="visually-hidden">Categoria dos materiais</span><select id="category">${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${filters.category===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="chip" id="favorites-filter" aria-pressed="${filters.saved}">☆ Meus favoritos</button></div><p class="result-count" id="material-count" aria-live="polite"></p><div class="grid" id="material-grid"></div><div class="load-more" id="more-wrap"></div><p class="source">Os tamanhos indicam o arquivo original. As imagens exibidas no portal são versões leves de visualização. Favoritos ficam salvos neste navegador.</p></div></section>`}
function filteredFiles(){return libraryFiles.filter(f=>(filters.category==='todos'||f.category===filters.category)&&(!filters.saved||favorites.has(f.id))&&norm([f.name,title(f),cats[f.category],fmt(f)].join(' ')).includes(norm(filters.query)))}
function renderMaterials(){const selected=filteredFiles();$('#material-count').textContent=`${selected.length} ${selected.length===1?'material encontrado':'materiais encontrados'}${filters.saved?' nos seus favoritos':''}`;$('#material-grid').className='grid'+(filters.category==='fotos'?' gallery':'');$('#material-grid').innerHTML=selected.length?selected.slice(0,filters.limit).map(materialCard).join(''):'<div class="empty"><h3>Nenhum material encontrado.</h3><p>Experimente outra palavra ou escolha uma categoria diferente.</p></div>';$('#more-wrap').innerHTML=selected.length>filters.limit?`<button class="button outline" id="load-more">Mostrar mais ${Math.min(24,selected.length-filters.limit)} materiais ↓</button>`:'';}
function faqPage(){return pageHead('PERGUNTAS FREQUENTES','Boas respostas fazem<br>parte de uma boa conversa.','Consulte as orientações dos cinco documentos oficiais. Encontre o assunto, leia a resposta e use o conteúdo para apoiar sua conversa com a escola.')+`<section class="section"><div class="wrap"><div class="toolbar"><label class="search"><span class="visually-hidden">Buscar perguntas frequentes</span><input type="search" id="faq-search" placeholder="Ex.: almoço, chuva, BNCC, agendamento…" value="${esc(faqFilter.query)}"></label></div><div class="tabs" aria-label="Temas das perguntas">${[['todos','Todos os temas'],...Object.entries(topics)].map(([id,t])=>`<button class="chip" data-topic="${id}" aria-pressed="${faqFilter.topic===id}">${t}</button>`).join('')}</div><p class="result-count" id="faq-count" aria-live="polite"></p><div id="faq-list" class="faq-list"></div><div class="callout">As respostas reproduzem os documentos do acervo. Para valores, datas e condições de contratação, confirme a informação vigente com a equipe do Castelo antes de fechar sua proposta.</div><a class="text-link" href="#biblioteca?categoria=faq">Acessar os cinco documentos completos ↗</a></div></section>`}
function renderFaq(){const list=faqs.filter(q=>(faqFilter.topic==='todos'||q.topic===faqFilter.topic)&&norm(q.question+' '+q.answer).includes(norm(faqFilter.query)));$('#faq-count').textContent=`${list.length} perguntas encontradas`;$('#faq-list').innerHTML=list.length?list.map(q=>`<details class="faq"><summary><span class="tag">${topics[q.topic]}</span>${esc(q.question)}</summary><div class="answer">${q.answer.split('\n').filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}<div class="card-actions"><button class="button outline small" data-copy-faq="${q.id}">Copiar resposta ⧉</button>${external(q.source,'Consultar documento original')}</div></div></details>`).join(''):'<div class="empty"><h3>Nenhuma resposta encontrada.</h3><p>Tente um termo mais curto ou selecione todos os temas.</p></div>';document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.topic===faqFilter.topic));}
const checkItems=['Formato da visita','Disponibilidade da data','Número previsto de participantes','Série e faixa etária dos estudantes','Objetivo pedagógico da escola','Horários de saída, chegada e retorno','Transporte','Alimentação','Acompanhamento e equipe da agência','Eventual kit lanche no trajeto','Necessidades de acessibilidade ou mobilidade','Alergias e restrições alimentares','Condições de saúde relevantes informadas pela escola','Itens incluídos no pacote da agência','Valores e condições comerciais','Responsabilidades da escola, da agência e do Castelo','Informações oficiais atualizadas disponibilizadas por O Castelo'];
function proposal(){return pageHead('PREPARE SUA PROPOSTA','Antes de confirmar,<br>alinhe cada detalhe.','Apresente claramente o que corresponde à experiência no Castelo e o que faz parte dos serviços organizados pela sua agência.')+`<section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">FORMATOS DE VISITA</span><h2>Encontre o formato<br>adequado para a escola.</h2></div><p>A escolha considera o número de alunos, os objetivos da escola, o interesse em exclusividade e a disponibilidade de agenda.</p></div><div class="proposals"><article class="proposal-card"><span class="eyebrow">COMPOR UMA DATA</span><h3>Agenda Compartilhada</h3><p>Permite reunir grupos de escolas diferentes na mesma data. A confirmação depende da composição mínima de 100 alunos no total, respeitando o máximo de 150 por dia.</p><p>É uma alternativa para grupos menores. O interesse em uma data ainda precisa ser confirmado pela equipe do Castelo.</p><a class="text-link" href="#duvidas?tema=04">Entenda a composição da agenda ↗</a></article><article class="proposal-card"><span class="eyebrow">RESERVAR PARA SEU GRUPO</span><h3>Agenda Exclusiva</h3><p>O Castelo fica reservado para uma única escola ou grupo. Pode ser escolhida por grupos com menos de 100 alunos, com condição comercial progressiva.</p><p>Para grupos a partir de 100 alunos, aplica-se a faixa correspondente, respeitando a capacidade máxima de 150 alunos por dia.</p><a class="text-link" href="#duvidas?tema=05">Consultar as condições do acervo ↗</a></article></div><div class="callout"><strong>Confirme a disponibilidade antes de fechar.</strong><p>Quando a escola contrata por meio da agência parceira, a reserva deve ser articulada previamente pela agência junto ao Castelo.</p></div>
<details class="faq"><summary>Tabela de referência do guia 2026</summary><div class="answer"><p>Valores por aluno para Agenda Exclusiva, conforme o material original. Esta tabela não é uma cotação nem confirmação de vigência. Valide as condições para a data desejada.</p><table class="price-table"><thead><tr><th scope="col">Quantidade de alunos</th><th scope="col">Valor por aluno</th></tr></thead><tbody>${[['30 a 39','685'],['40 a 49','545'],['50 a 59','453'],['60 a 69','387'],['70 a 79','338'],['80 a 89','300'],['90 a 99','270'],['100 a 150','267']].map(([q,v])=>`<tr><td>${q}</td><td>R$ ${v}</td></tr>`).join('')}</tbody></table>${source('Guia comercial, página 23')}</div></details>
<section class="section"><span class="eyebrow">CLAREZA NA APRESENTAÇÃO</span><h2>O que está incluído?</h2><div class="benefits"><div class="benefit"><h3>A experiência de O Castelo</h3><p>Programação pedagógica, estações temáticas, atividades lúdicas, mediação dos educadores, estrutura de recepção do grupo e almoço previsto na programação.</p></div><div class="benefit"><h3>O pacote da agência</h3><p>Os serviços combinados com a escola, como transporte, acompanhamento, monitoria, coordenação operacional, lanche no trajeto, seguro e comunicação com as famílias.</p></div></div>${source('FAQ — Valores, proposta financeira e contratação',find('1PH2LKr1e4X-MVk9xSqeMN-o98C4iON4y').url)}</section>
<section><div class="section-head"><div><span class="eyebrow">CHECKLIST DO PARCEIRO</span><h2>Pronto para apresentar<br>a proposta?</h2></div><button class="button outline small" data-view="${checklistId}">Abrir checklist A4 ↗</button></div><p class="result-count" id="check-count"></p><div class="check-progress"><span id="check-progress"></span></div><div class="checklist">${checkItems.map((t,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${checked.has(i)?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="hero-actions"><button class="button" id="copy-checklist">Copiar meu checklist ⧉</button><button class="button outline" id="reset-checklist">Limpar marcações</button></div><p class="source">As marcações ficam apenas neste navegador. Este checklist não envia informações nem confirma reservas.</p></section></div></section>`}
function updateCheck(){if($('#check-count')){$('#check-count').textContent=`${checked.size} de ${checkItems.length} pontos conferidos`;$('#check-progress').style.width=(checked.size/checkItems.length*100)+'%'}}
function showFile(id,trigger){const f=find(id);if(!f)return;guideCleanup?.();guideCleanup=null;$('#viewer').classList.toggle('guide-view',id===guideId);lastTrigger=trigger||document.activeElement;$('#viewer-title').textContent=title(f);let inner='';
 if(f.id===guideId){inner=window.CasteloGuide.html();}
 else if(f.category==='videos'){inner=`<div class="player"><iframe src="https://drive.google.com/file/d/${f.id}/preview" title="${esc(title(f))}" allow="autoplay; fullscreen; encrypted-media" allowfullscreen></iframe></div><p class="viewer-note">Vídeo original reproduzido pelo Google Drive. Se o player não carregar, use “Assistir no Drive”. A reprodução exige internet.</p>`;}
 else if(f.id===checklistId){inner=checklistPreview();}
 else if(f.preview){
  const preview=brandPreviewFiles[f.id]||f.preview;
  const brandClass=f.category==='marca'?'brand-preview'+(lightBrandBackgrounds.has(f.id)?' logo-on-light':''):'';
  const detail=brandPreviewFiles[f.id]?'Logotipo exibido na versão transparente para facilitar a leitura. O arquivo original está disponível abaixo.':'Prévia leve para consulta. Baixe o arquivo original no Drive para usar na sua campanha.';
  inner=`<img class="${brandClass}" src="${preview}" alt="${esc(title(f))}"><p class="viewer-note">${detail}</p>`;
 }
 else if(f.id===canvaId){inner=`<div class="callout"><h3>Prepare a condição da sua agência.</h3><p>Abra o arquivo no Canva e crie uma cópia para sua agência. Na sua cópia, personalize valor, validade, logo e contato antes de divulgar. O Canva pode solicitar uma conta própria para edição.</p></div>${external(canvaUrl,'Abrir modelo no Canva','button')}`;}
 else{inner=`<div class="doc-player"><iframe src="https://drive.google.com/file/d/${f.id}/preview" title="${esc(title(f))}"></iframe></div><p class="viewer-note">Se a prévia não abrir, consulte o original no Drive.</p>`;}
 $('#viewer-content').innerHTML=inner+`<div class="viewer-links">${external(f.url,f.category==='videos'?'Assistir no Drive':'Abrir original no Drive','button outline')}${f.id!==canvaId?external(`https://drive.google.com/uc?export=download&id=${encodeURIComponent(f.id)}`,f.id===guideId?'Baixar PDF original':'Baixar original','button outline'):''}<button class="button outline" data-copy-url="${f.id}">Copiar link ⧉</button></div><p class="viewer-note">${esc(f.name)} · ${fmt(f)}${f.bytes?' · '+size(f.bytes):''}</p>`;
 if(f.id===guideId)guideCleanup=window.CasteloGuide.mount($('#viewer-content'));
 if(!$('#viewer').open)$('#viewer').showModal();
}
function startHero(){
 const slides=[...document.querySelectorAll('.hero-photo')];
 const counter=$('#hero-count'),toggle=$('#hero-toggle');
 const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
 let index=0,timer=null,paused=reducedMotion.matches,destroyed=false,request=0;
 const clear=()=>{clearTimeout(timer);timer=null};
 const schedule=()=>{clear();if(!paused&&!document.hidden&&!destroyed)timer=setTimeout(()=>show(index+1),4000)};
 function updateToggle(){toggle.innerHTML=paused?'<span aria-hidden="true">▷</span> Reproduzir':'<span aria-hidden="true">Ⅱ</span> Pausar';toggle.setAttribute('aria-label',paused?'Retomar troca de fotos':'Pausar troca de fotos')}
 async function show(next){
  clear();const token=++request;next=(next+slides.length)%slides.length;
  slides[next].loading='eager';try{await slides[next].decode()}catch{schedule();return}
  if(destroyed||token!==request)return;
  index=next;slides.forEach((img,i)=>{img.classList.toggle('is-visible',i===index);img.setAttribute('aria-hidden',i!==index)});
  counter.textContent=String(index+1).padStart(2,'0')+' / '+slides.length;counter.setAttribute('aria-label',`Foto ${index+1} de ${slides.length}`);schedule();
 }
 $('#hero-prev').addEventListener('click',()=>show(index-1));
 $('#hero-next').addEventListener('click',()=>show(index+1));
 toggle.addEventListener('click',()=>{paused=!paused;if(paused)request++;updateToggle();schedule()});
 const onVisibility=()=>schedule();
 const onMotion=()=>{paused=reducedMotion.matches;updateToggle();schedule()};
 document.addEventListener('visibilitychange',onVisibility);reducedMotion.addEventListener('change',onMotion);
 updateToggle();schedule();
 return ()=>{destroyed=true;request++;clear();document.removeEventListener('visibilitychange',onVisibility);reducedMotion.removeEventListener('change',onMotion)};
}
function closeViewer(){$('#viewer').close()}
$('#viewer').addEventListener('close',()=>{guideCleanup?.();guideCleanup=null;$('#viewer').classList.remove('guide-view');$('#viewer-content').innerHTML='';if(lastTrigger?.isConnected)lastTrigger.focus()});
$('#close-viewer').addEventListener('click',closeViewer);
$('#viewer').addEventListener('click',e=>{if(e.target===$('#viewer'))closeViewer()});
function route(){const raw=location.hash.slice(1)||'inicio';const [routePath,search='']=raw.split('?');const [name,anchor]=routePath.split('/');const params=new URLSearchParams(search);const routes={inicio:home,conheca:know,vendas:sales,campanhas:campaigns,videos:videosPage,biblioteca:library,duvidas:faqPage,proposta:proposal};const next=routes[name]?name:'inicio';
 if(next===currentRoute&&anchor&&document.getElementById(anchor)){document.getElementById(anchor).scrollIntoView();return;}
 stopHero?.();stopHero=null;
 currentRoute=next;copyTexts={};if(next==='biblioteca')filters={category:cats[params.get('categoria')]?params.get('categoria'):'todos',query:'',saved:false,limit:24};if(next==='duvidas')faqFilter={topic:topics[params.get('tema')]?params.get('tema'):'todos',query:''};
 $('#main').innerHTML=routes[next]();$('#nav').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');document.querySelectorAll('.header a').forEach(a=>{const r=a.hash.slice(1);if(r===next||(r==='campanhas'&&next==='biblioteca'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 const titles={inicio:'Portal do Parceiro',conheca:'Conheça a experiência',vendas:'Apresente e venda',campanhas:'Materiais para campanhas',videos:'Vídeos',biblioteca:'Biblioteca completa',duvidas:'Perguntas frequentes',proposta:'Prepare sua proposta'};document.title=`${titles[next]} · O Castelo`;
 if(next==='inicio')stopHero=startHero();if(next==='biblioteca')renderMaterials();if(next==='duvidas')renderFaq();if(next==='proposta')updateCheck();
 window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});if(anchor)document.getElementById(anchor)?.scrollIntoView();
}
window.addEventListener('hashchange',route);
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView()});
$('#menu-button').addEventListener('click',()=>{const opened=$('#nav').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',opened)});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.view)showFile(b.dataset.view,b);
 if(b.dataset.copy)copyText(copyTexts[b.dataset.copy]);
 if(b.dataset.copyFaq){const q=faqs.find(q=>q.id===b.dataset.copyFaq);copyText(q.question+'\n\n'+q.answer+'\n\nFonte: '+q.source)}
 if(b.dataset.copyUrl)copyText(find(b.dataset.copyUrl).url);
 if(b.dataset.save){const id=b.dataset.save;if(favorites.has(id))favorites.delete(id);else favorites.add(id);writeStore('castelo:favorites',[...favorites]);document.querySelectorAll(`[data-save="${id}"]`).forEach(el=>{el.textContent=favorites.has(id)?'★':'☆';el.setAttribute('aria-pressed',favorites.has(id));el.setAttribute('aria-label',(favorites.has(id)?'Remover dos':'Adicionar aos')+' favoritos: '+title(find(id)))});toast(favorites.has(id)?'Material salvo nos seus favoritos.':'Material removido dos favoritos.');if(currentRoute==='biblioteca'&&filters.saved)renderMaterials();}
 if(b.dataset.topic){faqFilter.topic=b.dataset.topic;renderFaq()}
 if(b.id==='favorites-filter'){filters.saved=!filters.saved;b.setAttribute('aria-pressed',filters.saved);filters.limit=24;renderMaterials()}
 if(b.id==='load-more'){filters.limit+=24;renderMaterials()}
 if(b.id==='copy-checklist')copyText('CHECKLIST · O CASTELO\n\n'+checkItems.map((t,i)=>(checked.has(i)?'✓ ':'○ ')+t).join('\n'));
 if(b.id==='reset-checklist'){checked.clear();writeStore('castelo:checklist',[]);document.querySelectorAll('[data-check]').forEach(c=>c.checked=false);updateCheck();toast('Marcações removidas.')}
});
document.addEventListener('input',e=>{if(e.target.id==='material-search'){filters.query=e.target.value;filters.limit=24;renderMaterials()}if(e.target.id==='faq-search'){faqFilter.query=e.target.value;renderFaq()}});
document.addEventListener('change',e=>{if(e.target.id==='category'){filters.category=e.target.value;filters.limit=24;renderMaterials()}if(e.target.dataset.check!==undefined){const n=Number(e.target.dataset.check);e.target.checked?checked.add(n):checked.delete(n);writeStore('castelo:checklist',[...checked]);updateCheck()}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
$('#install').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;return;}lastTrigger=$('#install');$('#viewer-title').textContent='O Castelo sempre à mão';$('#viewer-content').innerHTML='<p>No iPhone ou iPad, abra este portal no Safari, toque em Compartilhar e escolha “Adicionar à Tela de Início”.</p><p>No Android ou computador, procure “Instalar aplicativo” ou “Adicionar à tela inicial” no menu do navegador, quando disponível.</p><p class="viewer-note">A leitura consultada pode continuar offline. Vídeos, arquivos do Drive e modelos no Canva precisam de internet.</p>';$('#viewer').showModal()});
function connection(){$('#connection').hidden=navigator.onLine}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
route();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

window.addEventListener('pageshow', async () => {
 const accessLink = document.querySelector('#nav a[href="/api/partner-login"]');
 if (!accessLink || !navigator.onLine) return;

 try {
  const response = await fetch('/api/partner-login', {
   method: 'POST',
   body: new URLSearchParams({action: 'session'}),
   cache: 'no-store'
  });
  if (response.status === 204) accessLink.textContent = 'Minha sessão';
  if (response.status === 401) accessLink.textContent = 'Entrar';
 } catch {
  // The portal can still render its existing offline view.
 }
});
